import {projectAnalytics,projectMindmap,statusLabel,PROJECT_TEMPLATES} from './core.mjs';
import {mount} from './vendor/pele-1.7.0.mjs';
import {bindMapPointerSelection} from './map-selection.mjs';
const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const ago=value=>value?new Date(value).toLocaleString(undefined,{month:'short',day:'numeric',hour:'2-digit',minute:'2-digit'}):'No updates yet';
const nodeButton=(n,extra='')=>`<button class="dash-record" data-dashboard-node="${n.id}"><span class="dash-record-icon type-${n.type}">${({decision:'◇',branch:'⑂',source:'↗',task:'▤',output:'▧'})[n.type]||'◎'}</span><span><strong>${esc(n.title)}</strong><small>${esc(extra||statusLabel(n.status))}</small></span><span aria-hidden="true">↗</span></button>`;
export function mountDashboard(container,w,projectId,actions={}){
 const a=projectAnalytics(w,projectId),p=w.projects.find(p=>p.id===projectId),mindmap=projectMindmap(w,projectId),ratio=a.originalGoals.percent;
 const attention=[...new Map([...a.blocked,...a.waiting,...a.reportedDone].map(n=>[n.id,n])).values()].slice(0,4);
 const maxActivity=Math.max(1,...a.activity.map(d=>d.count));
 const metric=(key,value,note,style='')=>`<article class="dash-metric ${style}"><span>${key}</span><strong>${value}</strong><small>${note}</small></article>`;
 container.innerHTML=`<div class="dashboard-toolbar"><div><span class="dash-live-dot"></span> Auto-generated from your project record <span class="dashboard-updated">· ${esc(ago(a.latest?.at))}</span></div><label>View template <select id="dashboard-template" aria-label="Project dashboard template"><option value="auto" ${!p.templateId||p.templateId==='auto'?'selected':''}>Auto · ${esc(a.template.title)}</option>${PROJECT_TEMPLATES.map(t=>`<option value="${t.id}" ${p.templateId===t.id?'selected':''}>${esc(t.title)}</option>`).join('')}</select></label></div>
 <div class="dashboard-metrics">${metric('Original goals with evidence',`${a.originalGoals.done}<em> / ${a.originalGoals.total}</em>`,ratio===null?'Add criteria to measure outcomes':`${ratio}% of recorded goals`,'metric-goals')}${metric('Ready to move',a.ready.length,'Active or proposed · prerequisites clear')}${metric('Waiting on other work',a.waiting.length,`${a.blocked.length} explicitly blocked item${a.blocked.length===1?'':'s'}`)}${metric('Reports to review',a.reportsToReview.length,'Source checkpoints · not verified outcomes')}</div>
 <article class="dash-next"><div class="dash-next-icon">↗</div><div><p class="eyebrow">PICK UP HERE</p><h2>${esc(a.next)}</h2><small>${esc(a.template.description)}</small></div><button id="dashboard-resume">Resume with AI ↗</button></article>
 <div class="dashboard-grid"><article class="dash-panel dash-map-panel"><header><div><p class="eyebrow">THE BIG PICTURE</p><h2>Your project, connected</h2></div><button id="dashboard-full-map">Open full map ↗</button></header><div id="dashboard-mindmap" class="dashboard-mindmap" aria-label="Project overview mindmap"></div><div class="dash-map-caption"><span>Pele mindmap · ${mindmap.shown} of ${mindmap.total} records</span><span>Grouped overview · dependencies in Flow view</span></div></article>
 <article class="dash-panel dash-work-panel"><header><div><p class="eyebrow">CURRENT RECORD</p><h2>Where the work stands</h2></div><span class="dash-count">${a.workTotal} items</span></header><div class="dash-status-list">${a.status.filter(s=>s.count).map(s=>`<div class="dash-status-row"><div><span><i class="status-dot status-${s.id}"></i>${esc(s.label)}</span><strong>${s.count}</strong></div><div class="dash-track" role="img" aria-label="${esc(s.label)}: ${s.count} of ${a.workTotal} work items"><span class="fill-${s.id}" style="width:${a.workTotal?100*s.count/a.workTotal:0}%"></span></div></div>`).join('')||'<p class="dash-empty">Add a task, decision or result to see the work here.</p>'}</div><p class="dash-footnote">Work items exclude goals and source reports. Completion labels reflect recorded evidence, not an independent audit.</p><div class="dash-template-stages">${a.template.stages.map((s,i)=>`<span><b>${String(i+1).padStart(2,'0')}</b>${esc(s)}</span>`).join('')}</div><small class="dash-footnote">Template prompts · stage completion is not inferred.</small></article>
 <article class="dash-panel dash-rhythm"><header><div><p class="eyebrow">YOUR WORK RHYTHM</p><h2>The last two weeks</h2></div><span><strong>${a.updates14d}</strong> updates</span></header><div class="dash-activity-bars" role="img" aria-label="${a.updates14d} recorded updates across ${a.activeDays} of the last 14 days">${a.activity.map(d=>`<div class="dash-day" title="${d.date}: ${d.count} updates"><span class="dash-day-value">${d.count||''}</span><span class="dash-day-track"><i style="height:${100*d.count/maxActivity}%" class="${d.count?'':'empty-day'}"></i></span><small>${d.date.slice(8)}</small></div>`).join('')}</div><div class="dash-chart-caption"><span>${a.activeDays} active day${a.activeDays===1?'':'s'} · ${esc(a.timeZone)}</span><span>Recorded updates, not hours or productivity</span></div></article>
 <article class="dash-panel"><header><div><p class="eyebrow">CLEAR THE PATH</p><h2>Needs a look</h2></div><span class="dash-count">${attention.length}</span></header>${attention.map(n=>nodeButton(n,a.waiting.some(x=>x.id===n.id)?'Waiting on prerequisites':statusLabel(n.status))).join('')||'<div class="dash-empty positive-empty">No explicit blockers or pending completion claims.<small>Source reports may still need evidence review.</small></div>'}</article>
 <article class="dash-panel"><header><div><p class="eyebrow">KEEP THE REASONING</p><h2>Decisions & offshoots</h2></div><button id="dashboard-new-decision">＋ Decision</button></header>${[...a.decisions.slice(0,2),...a.branches.slice(0,2)].map(n=>nodeButton(n,`${n.type==='branch'?'Offshoot':'Decision'} · ${statusLabel(n.status)}`)).join('')||'<p class="dash-empty">Save the next choice or offshoot here so its reason stays with the project.</p>'}</article>
 <article class="dash-panel dash-evidence"><header><div><p class="eyebrow">THE LATEST CONTEXT</p><h2>Evidence & checkpoints</h2></div><span class="dash-count">${a.sourcesTotal} total</span></header>${a.recentSources.slice(0,3).map(n=>nodeButton(n)).join('')||'<p class="dash-empty">Your first checkpoint will appear here. Reports stay separate from verified results.</p>'}</article>
 <article class="dash-panel dash-checkin"><header><div><p class="eyebrow">A USEFUL NEXT SESSION</p><h2>Your check-in template</h2></div><button id="dashboard-copy-checkin">Copy prompts</button></header><ul>${a.template.prompts.map(q=>`<li>${esc(q)}</li>`).join('')}</ul><footer><span>${a.providers.map(x=>`${esc(x.provider)} · ${x.count}`).join(' &nbsp; ')||'No provider-tagged checkpoints yet'}</span><button id="dashboard-activity">View activity →</button></footer></article></div>`;
 const jump=id=>{const original=id.startsWith('item_')?id.slice(5):id;if(w.nodes.some(n=>n.id===original&&n.projectId===projectId))actions.onNode?.(original);};
 container.querySelectorAll('[data-dashboard-node]').forEach(b=>b.onclick=()=>jump(b.dataset.dashboardNode));
 container.querySelector('#dashboard-template').onchange=e=>actions.onTemplate?.(e.target.value);
 container.querySelector('#dashboard-resume').onclick=()=>actions.onResume?.();
 container.querySelector('#dashboard-full-map').onclick=()=>actions.onMap?.();
 container.querySelector('#dashboard-activity').onclick=()=>actions.onActivity?.();
 container.querySelector('#dashboard-new-decision').onclick=()=>actions.onDecision?.();
 container.querySelector('#dashboard-copy-checkin').onclick=()=>actions.onCopy?.(`# ${p.title} · check-in\n\n${a.template.prompts.map(q=>q+'\n').join('\n')}\nEvidence reference:\nNext concrete action:`);
 const host=container.querySelector('#dashboard-mindmap');
 const diagram=mount(host,mindmap.source,{fontSize:15,padding:26,images:false,links:false,zoom:{always:true,controls:false,maxScale:3},idPrefix:'dashboardMindmap',onRender:()=>{
  for(const el of host.querySelectorAll('.pele-node[data-id]')){
   const id=el.getAttribute('data-id');if(!id.startsWith('item_'))continue;const n=w.nodes.find(n=>n.id===id.slice(5));if(!n)continue;
   el.dataset.status=n.status;el.setAttribute('role','button');el.setAttribute('tabindex','0');el.setAttribute('aria-label','Open '+n.title);el.onclick=()=>jump(n.id);el.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();jump(n.id);}};
  }
 }});
 const dispose=bindMapPointerSelection(host,jump);
 return {analytics:a,destroy(){dispose();diagram.destroy();}};
}
